import{_ as r,C as o,o as d,c as s,a2 as a,E as n}from"./chunks/framework.DBKUV7en.js";const m=JSON.parse('{"title":"0. この教科書について","description":"","frontmatter":{},"headers":[],"relativePath":"ch0/intro.md","filePath":"ch0/intro.md","lastUpdated":null}'),i={name:"ch0/intro.md"};function l(h,t,p,b,c,f){const e=o("TasteCompass");return d(),s("div",null,[t[0]||(t[0]=a('<h1 id="_0-この教科書について" tabindex="-1">0. この教科書について <a class="header-anchor" href="#_0-この教科書について" aria-label="Permalink to &quot;0. この教科書について&quot;">​</a></h1><p>同じ豆を、同じレシピで淹れたつもりなのに、昨日はおいしくて、今日はなぜか酸っぱい。家でコーヒーを淹れていると、こういう日があります。</p><p>この教科書は、その「なぜ?」を、理由から順番にほどいていくためのものです。こう淹れれば正解、というレシピ集ではありません。味が変わったときに、何を疑って、どこを動かせばいいのか。それを自分で考えられるようになるのが目標です。</p><h2 id="僕について" tabindex="-1">僕について <a class="header-anchor" href="#僕について" aria-label="Permalink to &quot;僕について&quot;">​</a></h2><p>プロのバリスタではありません。家でコーヒーを淹れているコーヒー好きです。</p><p>気になったことは、論文やお店の説明を調べて、条件を1つだけ変えて淹れ比べています。この教科書は、その「調べたこと」と「試したこと」をまとめたものです。読む人より少しだけ先を歩いている、くらいのつもりで書いています。</p><h2 id="こんな人に読んでほしい" tabindex="-1">こんな人に読んでほしい <a class="header-anchor" href="#こんな人に読んでほしい" aria-label="Permalink to &quot;こんな人に読んでほしい&quot;">​</a></h2><ul><li>豆を挽いて、家でドリップしている</li><li>器具はひと通りそろったのに、毎回味が違う</li><li>浅煎りを買うと、酸っぱいだけになってしまう</li><li>レシピ通りなのに、うまくいく日といかない日がある</li><li>特に困ってはいないけど、理屈を知って、もっと上手くなりたい</li></ul><h2 id="味を3つに分けて考える" tabindex="-1">味を3つに分けて考える <a class="header-anchor" href="#味を3つに分けて考える" aria-label="Permalink to &quot;味を3つに分けて考える&quot;">​</a></h2><p>コーヒーの味を考えるとき、僕は3つに分けています。</p><table tabindex="0"><thead><tr><th></th><th>何が決まるか</th><th>この教科書では</th></tr></thead><tbody><tr><td>素材(豆・焙煎・精製・水)</td><td>何が入っているか。味の個性</td><td>好みを探す</td></tr><tr><td>抽出(挽き目・比率・湯温など)</td><td>どれだけ、どの濃度で出すか。味のブレ</td><td>ブレを直す</td></tr><tr><td>届け方(フィルター・冷やし方・時間)</td><td>口当たりや、時間がたったときの変化</td><td>仕上げを整える</td></tr></tbody></table><p>まとめると、<strong>個性は素材で決まり、ブレは抽出で起きる</strong>。これがこの教科書の軸です。</p><p>ただ、これは研究の結論ではなく、いろいろな研究や情報を並べて僕が考えた「作業仮説」です。素材と抽出のどちらがどれだけ効くのかを、同じ実験で比べた研究は、まだ見つかっていません。焙煎度が湯温や時間より大きく味を変えた、という研究はあります(浸漬式で淹れた、豆1種類での実験です)。研究の条件は<a href="/coffee-textbook/appendix/studies">付録</a>にまとめました。</p><h2 id="ドリップグリッド" tabindex="-1">ドリップグリッド <a class="header-anchor" href="#ドリップグリッド" aria-label="Permalink to &quot;ドリップグリッド&quot;">​</a></h2><p>第2章の「抽出」の話では、この図を使います。抽出においては、まず濃度と抽出率を考える。この図の横軸と縦軸が、その2つです。ブレを直すための地図です。</p>',15)),n(e),t[1]||(t[1]=a('<p>横は、粉からどれだけ溶け出したか(抽出率)。左が「出きっていない」、右が「よく出ている」です。縦は、できたコーヒーの濃度です。上が「濃い」、下が「薄い」。真ん中の「ねらう場所」は、人によって少しずつ違います。</p><p>酸っぱい、苦い、と感じたら、まずこの図のどこにいるかを考えます。そうすると、次に何を変えればいいかが見えてきます。<a href="/coffee-textbook/ch1/sour-bitter">第3回</a>で、実際に使ってみます。</p><p>この図で分からないこともあります。豆の個性や香り、口当たりは、この図には出てきません。それから、家では濃度も抽出率も数字では測れません(測るには屈折計という専用の道具が要ります)。なので、この図は自分の舌で使う地図だと思ってください。</p><h2 id="読み方" tabindex="-1">読み方 <a class="header-anchor" href="#読み方" aria-label="Permalink to &quot;読み方&quot;">​</a></h2><p>ドリップに慣れていなければ、先に第1章の<a href="/coffee-textbook/basics/how-drip-works">ハンドドリップで、何が起きているか</a>と<a href="/coffee-textbook/basics/base-recipe">基準の一杯</a>を読むと、第2章が分かりやすくなります。そのあとは、最初から順番に読むのがおすすめです。困っていることが決まっていれば、<a href="/coffee-textbook/contents">目次</a>からその回だけ読んでも大丈夫です。分からない言葉は<a href="/coffee-textbook/glossary">用語集</a>で引けます。</p><p>エスプレッソ、ミルクを入れた飲み方は、この教科書では扱いません。</p><h2 id="noteと動画" tabindex="-1">noteと動画 <a class="header-anchor" href="#noteと動画" aria-label="Permalink to &quot;noteと動画&quot;">​</a></h2><p>実際に淹れ比べている様子は、動画で出しています(<a href="https://www.youtube.com/@kinotake_b" target="_blank" rel="noreferrer">YouTube</a>・<a href="https://www.instagram.com/kinotake_b/" target="_blank" rel="noreferrer">Instagram</a>)。日々のことは <a href="https://x.com/Kinotake_b" target="_blank" rel="noreferrer">X</a> と <a href="https://www.threads.com/@kinotake_b" target="_blank" rel="noreferrer">Threads</a> にも書いています。 実験の記録や、調べていて面白かったことは、<a href="https://note.com/kinotake_b" target="_blank" rel="noreferrer">note</a> に書いています。 この教科書は、その理屈の部分をまとめておく場所です。</p><h2 id="確かさの一覧-印の見方" tabindex="-1">確かさの一覧(印の見方) <a class="header-anchor" href="#確かさの一覧-印の見方" aria-label="Permalink to &quot;確かさの一覧(印の見方)&quot;">​</a></h2><p>各回の最後に、書いたことがどこまで確かなのかを、表にまとめています。そこでは、次の印を使います。</p><table tabindex="0"><thead><tr><th>印</th><th>意味</th></tr></thead><tbody><tr><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span></td><td>研究(論文や学会発表)で確かめられている。どこまで読んで確認したかは、各回に書きます</td></tr><tr><td><span class="stamp stamp-established ignore-header" tabindex="0" data-tip="信頼できる複数の情報源で、言っていることが一致している" aria-label="定説: 信頼できる複数の情報源で、言っていることが一致している">定説</span></td><td>信頼できる複数の情報源で、言っていることが一致している</td></tr><tr><td><span class="stamp stamp-shop ignore-header" tabindex="0" data-tip="お店やメーカーの説明。参考になるけれど、宣伝を含むこともある" aria-label="店の説明: お店やメーカーの説明。参考になるけれど、宣伝を含むこともある">店の説明</span></td><td>お店やメーカーの説明(参考になるけれど、宣伝を含むこともある)</td></tr><tr><td><span class="stamp stamp-tried ignore-header" tabindex="0" data-tip="僕の体験・感想" aria-label="試した: 僕の体験・感想">試した</span></td><td>僕の体験・感想</td></tr><tr><td><span class="stamp stamp-reasoning ignore-header" tabindex="0" data-tip="計算や、情報をつなげて考えたこと。研究そのものではない" aria-label="考察: 計算や、情報をつなげて考えたこと。研究そのものではない">考察</span></td><td>考察(計算や、情報をつなげて考えたこと。研究そのものではない)</td></tr><tr><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span></td><td>まだ確かめられていない</td></tr></tbody></table>',11))])}const k=r(i,[["render",l]]);export{m as __pageData,k as default};
